// Semana anterior (segunda a domingo) no fuso de Brasília e os anos de competência que cobrem os últimos 24 meses
const hoje = DateTime.now().setZone('America/Sao_Paulo').startOf('day');
const inicio = hoje.startOf('week').minus({ weeks: 1 });
const fim = inicio.plus({ days: 6 });
const anos = [...new Set([24, 12, 0].map(m => fim.minus({ months: m }).year))];
return [{ json: { inicio: inicio.toISODate(), fim: fim.toISODate(), anos } }];

// Boletim do Radar do Senado: votações nominais da semana + despesas da CEAPS acima do padrão do próprio senador.
// Entrada: itens do nó "Votações da semana" e o período do nó "Semana". Texto montado por modelo fixo (sem LLM).
const { inicio, fim, anos } = $('Semana').first().json;
const URL_CEAPS = ano => `https://adm.senado.gov.br/adm-dadosabertos/api/v1/senadores/despesas_ceaps/${ano}`;
const br = iso => iso.split('-').reverse().join('/');
const rs = v => 'R$ ' + v.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

// Quartil com interpolação linear (igual ao QUARTIL.INC do Excel)
function quartil(ordenados, q) {
  const pos = (ordenados.length - 1) * q;
  const base = Math.floor(pos);
  const resto = pos - base;
  return ordenados[base + 1] !== undefined ? ordenados[base] + resto * (ordenados[base + 1] - ordenados[base]) : ordenados[base];
}

// 1. Votações nominais: votação secreta traz os totais; votação aberta traz o voto de cada senador
const votacoes = $input.all().map(i => i.json).filter(v => v.identificacao).map(v => {
  const conta = sigla => (v.votos || []).filter(x => x.siglaVotoParlamentar === sigla).length;
  const secreta = v.votacaoSecreta === 'S';
  return {
    data: v.dataSessao,
    identificacao: v.identificacao,
    descricao: v.descricaoVotacao,
    secreta,
    sim: secreta ? v.totalVotosSim : conta('Sim'),
    nao: secreta ? v.totalVotosNao : conta('Não'),
    abstencao: secreta ? v.totalVotosAbstencao : conta('Abstenção'),
    link: `https://www25.senado.leg.br/web/atividade/materias/-/materia/${v.codigoMateria}`,
  };
});

// 2. CEAPS dos anos de competência que cobrem os últimos 24 meses
const despesas = [];
for (const ano of anos) {
  despesas.push(...(await this.helpers.httpRequest({ url: URL_CEAPS(ano), json: true })));
}
// Datas do documento fora do ano de competência (ex.: 0202, 2006): o histórico usa ano/mês de competência
const dataForaDoAno = despesas.filter(d => !d.data || Number(d.data.slice(0, 4)) !== d.ano).length;

// 3. Semana = data do documento entre segunda e domingo; histórico = 24 meses de competência até o mês de "fim"
const semana = despesas.filter(d => d.data && d.data >= inicio && d.data <= fim);
const idsSemana = new Set(semana.map(d => d.id));
const mesFim = Number(fim.slice(0, 4)) * 12 + Number(fim.slice(5, 7));
const historico = new Map();
for (const d of despesas) {
  const mes = d.ano * 12 + d.mes;
  if (idsSemana.has(d.id) || mes > mesFim || mes <= mesFim - 24) continue;
  const chave = `${d.codSenador}|${d.tipoDespesa}`;
  if (!historico.has(chave)) historico.set(chave, []);
  historico.get(chave).push(d.valorReembolsado);
}

const acima = [];
let semHistorico = 0;
for (const d of semana) {
  const h = (historico.get(`${d.codSenador}|${d.tipoDespesa}`) || []).sort((a, b) => a - b);
  if (h.length < 12) { semHistorico++; continue; }
  const q1 = quartil(h, 0.25), q3 = quartil(h, 0.75);
  const referencia = q3 + 3 * (q3 - q1);
  if (d.valorReembolsado > referencia) {
    acima.push({ id: d.id, data: d.data, senador: d.nomeSenador, tipo: d.tipoDespesa.trim(), valor: d.valorReembolsado, referencia, n_historico: h.length, fonte: URL_CEAPS(d.ano) });
  }
}
acima.sort((a, b) => b.valor - a.valor);

// 4. Texto (limite de 4.096 caracteres por mensagem no Telegram)
const linhas = [`Radar do Senado — semana de ${br(inicio)} a ${br(fim)}`, '', `Votações nominais no Plenário: ${votacoes.length}`];
if (!votacoes.length) linhas.push('Sem votações nominais na semana.');
for (const v of votacoes) {
  linhas.push(`• ${br(v.data).slice(0, 5)} · ${v.identificacao} — ${v.descricao.slice(0, 110)}${v.descricao.length > 110 ? '…' : ''}`,
    `  Sim ${v.sim} · Não ${v.nao} · Abstenção ${v.abstencao}${v.secreta ? ' · votação secreta' : ''}`, `  ${v.link}`);
}
const totalSemana = semana.reduce((s, d) => s + d.valorReembolsado, 0);
linhas.push('', `Cota parlamentar (CEAPS): ${semana.length} lançamentos com data do documento na semana, ${rs(totalSemana)}.`,
  `Acima da referência estatística do próprio histórico (Q3 + 3×IQR, mesmo senador e tipo de despesa, 24 meses, mínimo de 12 lançamentos): ${acima.length}. Ficar acima da referência não indica irregularidade.`);
const rodape = ['', `Não avaliados (menos de 12 lançamentos no histórico): ${semHistorico}.`,
  `Fonte: ${anos.map(URL_CEAPS).join(' ; ')}`,
  `Nota: ${dataForaDoAno} lançamentos dos arquivos têm data do documento fora do ano de competência; o histórico usa ano/mês de competência. Despesas com data na semana que forem lançadas depois não entram neste boletim.`];
let listados = 0;
for (const a of acima) {
  const item = `• ${a.senador} — ${a.tipo.split(',')[0].slice(0, 60)} — ${rs(a.valor)} em ${br(a.data)} (referência ${rs(a.referencia)}; ${a.n_historico} lançamentos no histórico)`;
  if ([...linhas, item, ...rodape].join('\n').length > 3900) break;
  linhas.push(item);
  listados++;
}
if (listados < acima.length) linhas.push(`• e mais ${acima.length - listados} (lista completa no JSON da execução)`);
const texto = [...linhas, ...rodape].join('\n');
// O nó do Telegram envia em Markdown: _ * ` [ precisam de escape (ex.: despesas_ceaps nas URLs)
const texto_telegram = texto.replace(/([_*`[])/g, '\\$1');

return [{ json: { inicio, fim, votacoes, ceaps: { lancamentos_semana: semana.length, total_semana: totalSemana, acima_da_referencia: acima, nao_avaliados: semHistorico, data_fora_do_ano: dataForaDoAno }, texto, texto_telegram } }];

// Registra a decisão. Envio para destino público: próxima etapa (por enquanto, só o Telegram do Luis).
// Sem resposta em 2 dias, o formulário expira e a decisão fica vazia (não aprovado).
const semana = $('Semana').first().json;
return [{ json: { inicio: semana.inicio, fim: semana.fim, decisao: $json['Decisão'] ?? null, aprovado: $json['Decisão'] === 'Aprovar' } }];
